// Code generated by rig. DO NOT EDIT.
//
// This file is rewritten on every run. Put changes in the service layer.

package api

import (
	"context"
	"fmt"
	"time"

	"github.com/simonjanss/rig/runtime/electric"
	"github.com/simonjanss/rig/runtime/serve"
	"github.com/simonjanss/rig/runtime/tenancy"
)

// DefaultElectricURL is the sync service configured when this was generated. A
// deployment can point somewhere else by building its own proxy.
const DefaultElectricURL = "http://electric:3000"

// ElectricRequired is whether this project decided it cannot serve without
// live sync.
//
// It comes from server-go's electric_required in rig.yaml, and it is what
// [CheckSyncService] does with a sync service that is not answering: false
// warns and carries on, true refuses to start and puts the sync service in the
// readiness check.
const ElectricRequired = false

// syncProbeTimeout bounds the one question asked at boot. It is inside the
// server's own MaxStartup, and short because the answer wanted here is "is it
// there" rather than "will it eventually be": a sync service still connecting
// to its database is reported as not serving, which is the honest answer and
// the one that comes back on its own.
const syncProbeTimeout = 5 * time.Second

// syncHint is what to tell somebody whose sync service is not there.
//
// The counterpart of the serve.Config.Hint the database has, and it is here
// for the same reason that one is a field: the address a shape route forwards
// to is a container in development and a deployed service in production, and
// printing the wrong one is worse than printing nothing.
const syncHint = "run `rig db up` to start the sync service, or set $ELECTRIC_URL"

// CheckSyncService asks the sync service whether it is serving, once, while
// the server is still starting.
//
// Called by [Mount] with whatever the application put in Parts.Proxy, so a
// project gets this without writing it. What it does with a bad answer is
// [ElectricRequired]: an error that stops the boot, or a warning and a server
// that starts anyway.
//
// A nil proxy is not a failure in either case, and returns without a word: rig
// cannot tell a project that has not built a front end for its shapes yet from
// one that forgot to wire the proxy, and [Mount] is where that is said.
//
// When this project said live sync is required, it also registers the probe as
// a readiness check, so an instance that loses the sync service is taken out
// of the load balancer rather than left in it answering nothing.
func CheckSyncService(ctx context.Context, app *serve.App, proxy *electric.Proxy) error {
	if proxy == nil {
		// Nothing to ask, and nothing said either: [Mount] is the caller that can tell
		// a nil Parts.Proxy from an absent one, and it already logged which. Saying it
		// again here would be the same line twice for every project that left the
		// field alone.
		return nil
	}

	probe, cancel := context.WithTimeout(ctx, syncProbeTimeout)
	defer cancel()

	if err := proxy.Health(probe); err != nil {
		if ElectricRequired {
			return fmt.Errorf("%w (%s)", err, syncHint)
		}
		app.Logger.WarnContext(ctx, "the sync service is not answering", "error", err, "hint", syncHint, "cost", "a shape with a fallback serves a snapshot; the rest answer 502")
		return nil
	}

	app.Logger.InfoContext(ctx, "the sync service is answering")

	if ElectricRequired {
		// Only when the project said so. By default a sync outage must not take every
		// replica out of the load balancer at once: the shapes with a fallback are
		// still serving, and so is every route that never touched the sync service.
		app.Ready("sync service", proxy.Health)
	}
	return nil
}

// Shapes is this server's live-sync half: the proxy the shape routes forward
// through, and one scoping function per shape.
//
// It is a field of [Handlers] rather than a second registration of its own, so
// mounting the API and mounting its shapes are the same call. They were two,
// and the cost of that was not the extra line: a shape route identifies its
// caller, refuses a request and drains at shutdown exactly the way every other
// route does, and every one of those was a field an application had to
// remember to set twice.
//
// A nil Proxy mounts nothing at all, which is what a project that generated
// its shapes and has not written the front end yet wants — the routes are
// absent rather than answering.
//
// A nil scope is not an error either: it means the shape is filtered by tenant
// and lifecycle and nothing else, which is exactly right for most tables.
//
// A soft-deletable table has a trash shape here as well as a live one, and a
// table that keeps its previous versions has a history shape. Neither is
// configured: the columns are what decide, the same way they decide whether
// the API has a GET /_deleted.
//
// Those two inherit the live shape's scope while their own field is nil. They
// carry the same table's rows, so a narrowing that mattered for the live shape
// almost always matters for the trash and the history too — and a narrowing
// the application has to remember to repeat on a route rig added is one that
// eventually does not get repeated. Set the field to scope them differently;
// setting it replaces the inherited scope rather than adding to it.
type Shapes struct {
	// Proxy forwards to the sync service. Nil mounts no shape routes.
	Proxy *electric.Proxy

	// App is the lifecycle the drain registers on.
	//
	// A shape route is a request the server is deliberately not answering yet, so
	// http.Server.Shutdown waits for it, and waits: nothing in the poll is late,
	// and Shutdown does not cancel a request's context. One open tab is a shutdown
	// that spends its budget waiting for the sync service to have news, after
	// which the flush, the sweep and the notification engine's own close each find
	// a deadline that has already passed.
	//
	// The drain runs first, once readiness is already false, which is the point at
	// which there is nothing left to gain from holding a subscription open. The
	// subscriber is told to come back and resumes from the same offset against a
	// replica that is still serving. Nothing is lost, because a poll that had not
	// answered had nothing in it yet.
	//
	// Inside Build it is the App that was handed in:
	//
	//	Shapes: api.Shapes{App: app, Proxy: proxy},
	//
	// Nil mounts the routes and registers no drain, and says so on the way past.
	// That is for the caller that has no App and owns the ending itself — a test
	// building this handler from a bare pool — rather than for forgetting.
	App *serve.App

	// IsAdmin reports whether a caller may subscribe to a shape marked admin-only.
	// Nil refuses every one of them, which is the safe way to leave it
	// unconfigured.
	IsAdmin func(tenancy.Claims) bool

	Lesson         LessonScope
	LessonDeleted  LessonDeletedScope
	LessonVersions LessonVersionsScope
}
